//! W2: spec/data/spec-data.json is a deterministic projection of the book.
//! It is regenerated byte for byte from the chapters, every chapter hash in
//! it is the chapter's footer, its method table is the reference
//! evaluator's, and its W-rules are the ones section 7 lists.
use rce_spec_check::specdata::export;
use serde_json::Value;
use std::path::Path;

fn spec() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf()
}

#[test]
fn checked_in_data_is_the_regenerated_data() {
    let a = export(&spec());
    let b = export(&spec());
    assert_eq!(a, b, "export is not deterministic");
    let have = std::fs::read_to_string(spec().join("data/spec-data.json")).unwrap();
    assert!(have == a, "spec/data/spec-data.json is stale: run `cargo run --release --bin rce-spec-data`");
    let t = std::fs::read_to_string(spec().join("data/spec-tables.json")).unwrap();
    assert!(t == rce_spec_check::specread::tables_of(&a), "spec/data/spec-tables.json is stale: run `rce-spec-data`");
}

#[test]
fn data_has_every_table() {
    let v: Value = serde_json::from_str(&export(&spec())).unwrap();
    assert_eq!(v["chapters"].as_object().unwrap().len(), 18);
    for g in ["grammar", "grammar_06"] {
        assert_eq!(v[g]["lalr1"]["conflicts"].as_array().unwrap().len(), 0, "{g}");
        assert!(v[g]["lalr1"]["action"].as_array().unwrap().len() > 1000, "{g}");
    }
    let w = v["w_rules"]["rules"].as_object().unwrap();
    for r in ["W-REC-1", "W-TY-1", "W-SAFE-1", "W-MOD-2", "W-NAME-1", "W-LOOP-1"] {
        assert!(w.contains_key(r), "{r} missing");
    }
    // Every rule section 7 names has a text in section 7 or Appendix C.
    let c = v["w_rules_06"]["rules"].as_object().unwrap();
    for r in v["w_rules"]["mentioned"].as_array().unwrap() {
        let r = r.as_str().unwrap();
        assert!(w.contains_key(r) || c.contains_key(r), "{r} has no definition");
    }
    let n = v["edges"]["rules"].as_object().unwrap();
    assert_eq!(n.len(), 11, "N1..N11: {:?}", n.keys().collect::<Vec<_>>());
    let text = v["methods"]["table"].as_array().unwrap().iter().find(|r| r["receiver"] == "Text").unwrap();
    assert!(text["methods"].as_array().unwrap().iter().any(|m| m == "sha256"));
}
